struct DeployEnvGuard(Option<std::ffi::OsString>);

impl DeployEnvGuard {
    fn enable() -> Self {
        let previous = std::env::var_os("DEPLOY");
        unsafe {
            std::env::set_var("DEPLOY", "1");
        }
        Self(previous)
    }
}

impl Drop for DeployEnvGuard {
    fn drop(&mut self) {
        match self.0.as_ref() {
            Some(value) => unsafe {
                std::env::set_var("DEPLOY", value)
            },
            None => unsafe {
                std::env::remove_var("DEPLOY")
            },
        }
    }
}

#[test]
fn proc_macro_build_modes_are_covered() {
    let tests = trybuild::TestCases::new();

    tests.pass("tests/fixtures/pass.rs");

    let _guard = DeployEnvGuard::enable();
    tests.compile_fail("tests/fixtures/deploy_blocked.rs");
}
